      "replace": "def _resolve_max_batch_size_bytes() -> Optional[int]:
    """Return the configured batch byte limit, or None to keep the exporter default.
    Supports optional suffixes (KB, MB, GB) for human‑readable sizes.
    """
    raw_value = os.environ.get(LANGFUSE_OTEL_MAX_BATCH_SIZE_BYTES, "").strip()
    if not raw_value:
        return None

    # Accept plain integer bytes
    if raw_value.isascii() and raw_value.isdigit() and int(raw_value) > 0:
        return int(raw_value)

    # Accept values with unit suffixes, e.g., "256KB", "1mb", "2GB"
    match = re.fullmatch(r"(?P<number>\d+)(?P<unit>[kKmMgG][bB]?)?", raw_value)
    if match:
        number = int(match.group("number"))
        unit = match.group("unit")
        multiplier = 1
        if unit:
            unit = unit.lower()
            if unit.startswith('k'):
                multiplier = 1024
            elif unit.startswith('m'):
                multiplier = 1024 * 1024
            elif unit.startswith('g'):
                multiplier = 1024 * 1024 * 1024
        value = number * multiplier
        if value > 0:
            return value

    langfuse_logger.warning(
        "Invalid %s=%r. Expected a positive integer or a size with KB/MB/GB suffix. Using the default limit.",
        LANGFUSE_OTEL_MAX_BATCH_SIZE_BYTES,
        raw_value,
    )
    return None"
