  "test": "import pytest
from langfuse._client.span_processor import LangfuseSpanProcessor
from langfuse._client.environment_variables import LANGFUSE_OTEL_MAX_BATCH_SIZE_BYTES

class NoOpSpanExporter:
    def export(self, spans):
        from opentelemetry.sdk.trace.export import SpanExportResult
        return SpanExportResult.SUCCESS
    def shutdown(self):
        pass

def test_resolve_max_batch_size_bytes_with_suffix(monkeypatch):
    # Set env var with KB suffix
    monkeypatch.setenv(LANGFUSE_OTEL_MAX_BATCH_SIZE_BYTES, "256KB")
    processor = LangfuseSpanProcessor(
        public_key="pk-test",
        secret_key="sk-test",
        base_url="http://localhost",
        span_exporter=NoOpSpanExporter(),
    )
    try:
        exporter = processor._span_exporter  # BatchSpanProcessor stores the exporter here
        # OTLPSpanExporter stores the limit in the attribute 'max_request_size'
        max_size = getattr(exporter, "max_request_size", getattr(exporter, "_max_request_size", None))
        assert max_size == 256 * 1024
    finally:
        processor.shutdown()"
}
